.digi-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dfe6ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.digi-sim-container .digi-sim-header {
    background: linear-gradient(135deg, #1a5276 0%, #2980b9 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(26,82,118,0.3);
    text-align: center;
}

.digi-sim-container .digi-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.digi-sim-container .digi-sim-header p {
    margin: 0;
    font-size: 1.1rem;
    opacity: 0.9;
}

.digi-sim-container .digi-sim-period-counter {
    text-align: center;
    font-size: 1.2rem;
    color: #555;
    margin-bottom: 25px;
    font-weight: 600;
}

.digi-sim-container .digi-sim-period-counter span {
    margin: 0 4px;
}

.digi-sim-container .digi-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}

.digi-sim-container .digi-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-left: 4px solid #bdc3c7;
}

.digi-sim-container .digi-sim-status-card:hover {
    transform: translateY(-4px);
}

.digi-sim-container .digi-sim-card-budget { border-left-color: #f39c12; }
.digi-sim-container .digi-sim-card-dt { border-left-color: #3498db; }
.digi-sim-container .digi-sim-card-retention { border-left-color: #27ae60; }
.digi-sim-container .digi-sim-card-ebitda { border-left-color: #2ecc71; }
.digi-sim-container .digi-sim-card-adoption { border-left-color: #9b59b6; }
.digi-sim-container .digi-sim-card-rapido { border-left-color: #e74c3c; }

.digi-sim-container .digi-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.digi-sim-container .digi-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #2c3e50;
}

.digi-sim-container .digi-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 20px 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #3498db;
    font-size: 0.95rem;
    line-height: 1.6;
    color: #444;
}

.digi-sim-container .digi-sim-event-alert {
    background: linear-gradient(135deg, #ffeaa7 0%, #fdcb6e 100%);
    border-radius: 14px;
    padding: 18px 22px;
    margin-bottom: 25px;
    border-left: 5px solid #f39c12;
    font-size: 0.92rem;
    line-height: 1.5;
    color: #856404;
}

.digi-sim-container .digi-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.digi-sim-container .digi-sim-controls h3 {
    color: #1a5276;
    font-size: 1.3rem;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #ebf5fb;
}

.digi-sim-container .digi-sim-controls h4 {
    color: #2c3e50;
    font-size: 1rem;
    margin: 20px 0 10px 0;
    font-weight: 600;
}

.digi-sim-container .digi-sim-controls p {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 10px;
}

.digi-sim-container .digi-sim-initiatives {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 8px;
    margin-bottom: 10px;
}

.digi-sim-container .digi-sim-init-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 14px;
    background: #f8f9fa;
    border: 2px solid #e9ecef;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s;
    margin: 0;
    font-size: 0.88rem;
}

.digi-sim-container .digi-sim-init-card:hover {
    border-color: #3498db;
    background: #ebf5fb;
}

.digi-sim-container .digi-sim-init-card input[type="checkbox"] {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
}

.digi-sim-container .digi-sim-budget-counter {
    background: #f0f8ff;
    border: 2px solid #3498db;
    border-radius: 10px;
    padding: 12px 18px;
    margin: 15px 0;
    font-size: 1rem;
    font-weight: 600;
    text-align: center;
    color: #2c3e50;
}

.digi-sim-container .digi-sim-budget-counter #budgetCounter {
    color: #27ae60;
    font-size: 1.1rem;
}

.digi-sim-container .digi-sim-select {
    margin-bottom: 10px;
    border-radius: 8px;
    border: 2px solid #e9ecef;
    padding: 10px 14px;
    font-size: 0.9rem;
}

.digi-sim-container .digi-sim-select:focus {
    border-color: #3498db;
    box-shadow: 0 0 0 3px rgba(52,152,219,0.15);
}

.digi-sim-container .digi-sim-incentive-row {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 10px 0;
}

.digi-sim-container .digi-sim-slider {
    flex: 1;
    min-width: 120px;
}

.digi-sim-container .digi-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 30px;
    flex-wrap: wrap;
}

.digi-sim-container .digi-sim-submit {
    background: linear-gradient(135deg, #1a5276 0%, #2980b9 100%);
    border: none;
    border-radius: 12px;
    padding: 14px 40px;
    font-size: 1.1rem;
    font-weight: 600;
    box-shadow: 0 4px 12px rgba(41,128,185,0.3);
    transition: all 0.3s;
}

.digi-sim-container .digi-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(41,128,185,0.4);
}

.digi-sim-container .digi-sim-undo {
    border-radius: 10px;
    padding: 8px 20px;
}

.digi-sim-container .digi-sim-charts-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 20px;
    margin-bottom: 25px;
}

.digi-sim-container .digi-sim-chart {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 300px;
}

.digi-sim-container .digi-sim-history {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    overflow-x: auto;
}

.digi-sim-container .digi-sim-history .table {
    margin: 0;
}

@media (max-width: 768px) {
    .digi-sim-container .digi-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .digi-sim-container .digi-sim-initiatives {
        grid-template-columns: 1fr;
    }
    .digi-sim-container .digi-sim-charts-row {
        grid-template-columns: 1fr;
    }
    .digi-sim-container .digi-sim-header h1 {
        font-size: 1.4rem;
    }
    .digi-sim-container .digi-sim-value {
        font-size: 1.3rem;
    }
}

@media (max-width: 480px) {
    .digi-sim-container {
        padding: 12px;
    }
    .digi-sim-container .digi-sim-status-cards {
        grid-template-columns: 1fr;
    }
}

