(function() {
    'use strict';

    class DigitalTransformAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Gran Salto';
            this.version = '1.1.0';
            this.INITIATIVES = {
                app: { cost: 1800, dims: { cx: 2.5, tech: 1.5 }, adopt: 5, retain: 8, lead: 2 },
                route_ai: { cost: 620, dims: { ops: 2.0, tech: 1.0 }, adopt: 3, retain: 2, lead: 1 },
                erp_api: { cost: 180, dims: { tech: 1.5, ops: 0.8 }, adopt: 2, retain: 0, lead: 1 },
                whatsapp: { cost: 95, dims: { cx: 1.0, tech: 0.5 }, adopt: 8, retain: 5, lead: 1 },
                training: { cost: 340, dims: { culture: 2.0 }, adopt: 20, retain: 3, lead: 1 },
                change_mgmt: { cost: 280, dims: { culture: 1.5, strategy: 0.8 }, adopt: 15, retain: 2, lead: 1 },
                champions: { cost: 120, dims: { culture: 1.2 }, adopt: 12, retain: 1, lead: 1 },
                loyalty: { cost: 480, dims: { cx: 2.0 }, adopt: 3, retain: 12, lead: 1 },
                credit_tool: { cost: 390, dims: { cx: 1.5, ops: 0.5 }, adopt: 2, retain: 8, lead: 1 },
                portal: { cost: 680, dims: { cx: 2.2, tech: 1.0 }, adopt: 5, retain: 10, lead: 2 },
                analytics: { cost: 520, dims: { strategy: 2.5, ops: 1.0 }, adopt: 4, retain: 3, lead: 1 },
                competitive: { cost: 85, dims: { strategy: 1.2 }, adopt: 1, retain: 1, lead: 1 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    budget: 4200,
                    budgetSpent: 0,
                    ebitdaMargin: 6.2,
                    customerRetention: 100,
                    employeeAdoption: 15,
                    rapidoShare: 26,
                    matCx: 2.8,
                    matOps: 4.1,
                    matStrategy: 3.2,
                    matCulture: 3.8,
                    matTech: 4.5,
                    dtScore: 3.7,
                    salesReps: 180,
                    selectedInits: [],
                    coalition: 'cross_functional',
                    commStrategy: 'phased',
                    incentiveDigital: 40,
                    bimboAccepted: false,
                    endgame: '',
                    dtScoreHistory: [],
                    ebitdaHistory: [],
                    retentionHistory: [],
                    adoptionHistory: [],
                    rapidoHistory: [],
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    round: 1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            decisions.round = period;

            if (period === 1) {
                var checks = document.querySelectorAll('.init-check:checked');
                var selected = [];
                var totalCost = 0;
                var self = this;
                checks.forEach(function(cb) {
                    selected.push(cb.value);
                    totalCost += self.INITIATIVES[cb.value].cost;
                });

                if (selected.length < 4) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('min_init_warning'), 'warning'
                    );
                    return false;
                }
                if (selected.length > 6) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('max_init_warning'), 'warning'
                    );
                    return false;
                }
                if (totalCost > 4200) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_warning'), 'warning'
                    );
                    return false;
                }

                decisions.selectedInits = selected;
                decisions.totalCost = totalCost;

                var coalitionEl = document.getElementById('coalitionSelect');
                decisions.coalition = coalitionEl ? coalitionEl.value : 'cross_functional';

                var commEl = document.getElementById('commSelect');
                decisions.commStrategy = commEl ? commEl.value : 'phased';

                var sliderEl = document.getElementById('incentiveSlider');
                decisions.incentiveDigital = sliderEl ? parseInt(sliderEl.value) : 40;

            } else if (period === 2) {
                var accelEl = document.getElementById('accelSelect');
                decisions.budgetAccel = accelEl ? accelEl.value : 'maintain';

                var attrEl = document.getElementById('attritionSelect');
                decisions.attritionResponse = attrEl ? attrEl.value : 'communication';

                var bimboEl = document.getElementById('bimboSelect');
                decisions.bimboDecision = bimboEl ? bimboEl.value : 'negotiate';

            } else if (period === 3) {
                var endEl = document.getElementById('endgameSelect');
                decisions.endgame = endEl ? endEl.value : 'distributor4';
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var eventMsg = '';
            var self = this;

            if (period === 1) {
                ds.selectedInits = d.selectedInits || [];
                ds.coalition = d.coalition;
                ds.commStrategy = d.commStrategy;
                ds.incentiveDigital = d.incentiveDigital;
                ds.budgetSpent = d.totalCost || 0;
                ds.budget = 4200 - ds.budgetSpent;

                var adoptionGain = 0;
                var retentionGain = 0;
                ds.selectedInits.forEach(function(id) {
                    var init = self.INITIATIVES[id];
                    if (!init) return;
                    var factor = init.lead === 1 ? 1.0 : 0.4;
                    Object.keys(init.dims).forEach(function(dim) {
                        var key = 'mat' + dim.charAt(0).toUpperCase() + dim.slice(1);
                        var current = ds[key] || 0;
                        var gain = init.dims[dim] * factor;
                        var diminish = 1 - (current / 12);
                        ds[key] = Math.min(10, current + gain * diminish);
                    });
                    adoptionGain += init.adopt * factor;
                    retentionGain += init.retain * factor;
                });

                var coalitionMod = 1.0;
                if (d.coalition === 'ceo_only') {
                    coalitionMod = 0.6;
                } else if (d.coalition === 'include_reps') {
                    coalitionMod = 1.3;
                    ds.matCulture = Math.min(10, ds.matCulture + 0.5);
                }
                adoptionGain *= coalitionMod;

                if (d.commStrategy === 'full') {
                    adoptionGain += 10;
                    retentionGain -= 3;
                } else if (d.commStrategy === 'need_to_know') {
                    adoptionGain -= 5;
                    retentionGain += 2;
                }

                var digitalPct = d.incentiveDigital || 40;
                adoptionGain += (digitalPct - 40) * 0.3;
                var ebitdaImpact = -(digitalPct - 40) * 0.02;

                ds.employeeAdoption = Math.min(100, Math.max(0, ds.employeeAdoption + adoptionGain));
                ds.customerRetention = Math.max(0, Math.min(100, ds.customerRetention - 5 + retentionGain * 0.3));

                var spendingEffect = -(ds.budgetSpent / 2840) * 0.5;
                ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin + spendingEffect + ebitdaImpact);

                ds.rapidoShare = Math.min(50, ds.rapidoShare + 4);

                if (Math.random() < 0.5) {
                    eventMsg += window.mySimulation.t('event_whatsapp');
                    if (ds.selectedInits.indexOf('whatsapp') === -1) {
                        ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.3);
                    }
                }

            } else if (period === 2) {
                var adoptionGain2 = 0;
                var retentionGain2 = 0;
                ds.selectedInits.forEach(function(id) {
                    var init = self.INITIATIVES[id];
                    if (!init) return;
                    if (init.lead === 2) {
                        var remaining = 0.6;
                        Object.keys(init.dims).forEach(function(dim) {
                            var key = 'mat' + dim.charAt(0).toUpperCase() + dim.slice(1);
                            var current = ds[key] || 0;
                            var gain = init.dims[dim] * remaining;
                            var diminish = 1 - (current / 12);
                            ds[key] = Math.min(10, current + gain * diminish);
                        });
                        adoptionGain2 += init.adopt * remaining;
                        retentionGain2 += init.retain * remaining;
                    }
                });

                if (d.budgetAccel === 'invest_more') {
                    ds.budgetSpent += 400;
                    ds.budget -= 400;
                    ds.matTech = Math.min(10, ds.matTech + 0.5);
                    ds.matCx = Math.min(10, ds.matCx + 0.5);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.2);
                } else if (d.budgetAccel === 'descope') {
                    ds.budget += 200;
                    ds.budgetSpent -= 200;
                    ds.matTech = Math.max(2, ds.matTech - 0.3);
                }

                if (d.attritionResponse === 'bonus') {
                    ds.budgetSpent += 280;
                    ds.budget -= 280;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 8);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.15);
                } else if (d.attritionResponse === 'communication') {
                    ds.salesReps -= 8;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 5);
                    ds.matCulture = Math.min(10, ds.matCulture + 0.3);
                } else if (d.attritionResponse === 'accept') {
                    ds.salesReps -= 28;
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption - 5);
                    ds.customerRetention = Math.max(0, ds.customerRetention - 6);
                    ds.ebitdaMargin += 0.4;
                }

                if (d.bimboDecision === 'accept') {
                    ds.budget += 800;
                    ds.bimboAccepted = true;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 3);
                    ds.matCx = Math.min(10, ds.matCx + 0.3);
                } else if (d.bimboDecision === 'negotiate') {
                    ds.budget += 400;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 1);
                } else {
                    ds.matStrategy = Math.min(10, ds.matStrategy + 0.5);
                }

                ds.employeeAdoption = Math.min(100, Math.max(0, ds.employeeAdoption + adoptionGain2));
                ds.customerRetention = Math.max(0, Math.min(100, ds.customerRetention + retentionGain2 * 0.2));

                var opsGain = (ds.matOps - 4.1) * 0.15;
                ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin + opsGain);

                eventMsg += window.mySimulation.t('event_sunat');
                if (ds.selectedInits.indexOf('erp_api') === -1) {
                    ds.budgetSpent += 250;
                    ds.budget -= 250;
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.3);
                    eventMsg += '<br>' + window.mySimulation.t('event_sunat_penalty');
                }

                if (Math.random() < 0.25) {
                    eventMsg += '<br>' + window.mySimulation.t('event_blackout');
                    if (ds.selectedInits.indexOf('route_ai') !== -1) {
                        ds.customerRetention = Math.max(0, ds.customerRetention - 1);
                    } else {
                        ds.customerRetention = Math.max(0, ds.customerRetention - 4);
                    }
                }

                var rapidoGrowth = ds.selectedInits.indexOf('app') !== -1 ? 1.5 : 3.5;
                ds.rapidoShare = Math.min(50, ds.rapidoShare + rapidoGrowth);

            } else if (period === 3) {
                ds.endgame = d.endgame;

                if (d.endgame === 'distributor4') {
                    ds.matOps = Math.min(10, ds.matOps + 1.0);
                    ds.matTech = Math.min(10, ds.matTech + 0.5);
                    ds.ebitdaMargin += 0.8;
                    ds.customerRetention = Math.min(100, ds.customerRetention + 3);
                    if (ds.matOps >= 7) {
                        ds.ebitdaMargin += 0.5;
                        ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 5);
                    }
                } else if (d.endgame === 'platform') {
                    ds.matCx = Math.min(10, ds.matCx + 1.5);
                    ds.matStrategy = Math.min(10, ds.matStrategy + 1.0);
                    ds.ebitdaMargin -= 0.5;
                    if (ds.matCx >= 6.5 && ds.matTech >= 6.5) {
                        ds.ebitdaMargin += 1.5;
                        ds.rapidoShare = Math.max(0, ds.rapidoShare - 5);
                    }
                    if (ds.bimboAccepted) {
                        ds.matStrategy = Math.max(2, ds.matStrategy - 0.8);
                    }
                } else if (d.endgame === 'logistics') {
                    ds.matOps = Math.min(10, ds.matOps + 1.5);
                    ds.ebitdaMargin += 0.3;
                    ds.customerRetention = Math.max(0, ds.customerRetention - 8);
                    ds.employeeAdoption = Math.min(100, ds.employeeAdoption - 10);
                    if (ds.matOps >= 7) {
                        ds.ebitdaMargin += 1.0;
                    }
                }

                if (Math.random() < 0.7) {
                    eventMsg += window.mySimulation.t('event_series_b');
                    ds.rapidoShare = Math.min(50, ds.rapidoShare + 3);
                    if (d.endgame === 'platform') {
                        ds.rapidoShare = Math.min(50, ds.rapidoShare + 2);
                    }
                }

                if (Math.random() < 0.35) {
                    if (eventMsg) eventMsg += '<br>';
                    eventMsg += window.mySimulation.t('event_disintermediation');
                    ds.customerRetention = Math.max(0, ds.customerRetention - 3);
                    ds.ebitdaMargin = Math.max(0, ds.ebitdaMargin - 0.4);
                }

                ds.employeeAdoption = Math.min(100, ds.employeeAdoption + 3);
                var cxEffect = (ds.matCx - 2.8) * 0.8;
                ds.customerRetention = Math.min(100, ds.customerRetention + cxEffect * 0.3);
            }

            ds.dtScore = Math.round(((ds.matCx + ds.matOps + ds.matStrategy + ds.matCulture + ds.matTech) / 5) * 10) / 10;
            ds.ebitdaMargin = Math.round(Math.max(0, Math.min(15, ds.ebitdaMargin)) * 10) / 10;
            ds.customerRetention = Math.round(Math.max(0, Math.min(100, ds.customerRetention)) * 10) / 10;
            ds.employeeAdoption = Math.round(Math.max(0, Math.min(100, ds.employeeAdoption)) * 10) / 10;
            ds.rapidoShare = Math.round(Math.max(0, Math.min(50, ds.rapidoShare)) * 10) / 10;

            ds.dtScoreHistory.push(ds.dtScore);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.retentionHistory.push(ds.customerRetention);
            ds.adoptionHistory.push(ds.employeeAdoption);
            ds.rapidoHistory.push(ds.rapidoShare);
            ds.eventLog = eventMsg;

            if (eventMsg) {
                var alertEl = document.getElementById('eventAlert');
                var textEl = document.getElementById('eventText');
                if (alertEl) alertEl.style.display = 'block';
                if (textEl) textEl.innerHTML = eventMsg;
            }

            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod, domainState: ds });
            }, 500);

            return {
                period: period,
                dtScore: ds.dtScore,
                customerRetention: ds.customerRetention,
                ebitdaMargin: ds.ebitdaMargin,
                employeeAdoption: ds.employeeAdoption,
                rapidoShare: ds.rapidoShare,
                budgetRemaining: ds.budget,
                events: eventMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                function(v) { return 'PEN ' + Math.round(v).toLocaleString() + 'K'; });
            uiManager.bind('dtScoreDisplay', 'domainState.dtScore',
                function(v) { return v.toFixed(1) + '/10'; });
            uiManager.bind('retentionDisplay', 'domainState.customerRetention',
