        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var briefEl = document.getElementById('briefingText');
            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');

            var t = window.mySimulation && window.mySimulation.t
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            if (briefEl) {
                if (period === 1) {
                    briefEl.innerHTML = t('briefing_r1');
                } else if (period === 2) {
                    briefEl.innerHTML = t('briefing_r2');
                } else {
                    briefEl.innerHTML = t('briefing_r3');
                }
            }

            if (r1) r1.style.display = period === 1 ? 'block' : 'none';
            if (r2) r2.style.display = period === 2 ? 'block' : 'none';
            if (r3) r3.style.display = period >= 3 ? 'block' : 'none';

            if (period === 1 && state.domainState) {
                var ds = state.domainState;
                if (ds.selectedInits && ds.selectedInits.length) {
                    document.querySelectorAll('.init-check').forEach(function(cb) {
                        cb.checked = ds.selectedInits.indexOf(cb.value) !== -1;
                    });
                }
                var coalitionEl = document.getElementById('coalitionSelect');
                if (coalitionEl && ds.coalition) coalitionEl.value = ds.coalition;
                var commEl = document.getElementById('commSelect');
                if (commEl && ds.commStrategy) commEl.value = ds.commStrategy;
                var sliderEl = document.getElementById('incentiveSlider');
                if (sliderEl && ds.incentiveDigital != null) {
                    sliderEl.value = ds.incentiveDigital;
                    var volPct = document.getElementById('volumePct');
                    var digPct = document.getElementById('digitalPct');
                    if (volPct) volPct.textContent = (100 - ds.incentiveDigital) + '%';
                    if (digPct) digPct.textContent = ds.incentiveDigital + '%';
                }
                var counter = document.getElementById('budgetCounter');
                if (counter) {
                    var total = 0;
                    document.querySelectorAll('.init-check:checked').forEach(function(cb) {
                        total += parseInt(cb.getAttribute('data-cost'));
